usage.code:
// The normal case needs no code: add the component, type the key.

// A line that takes values. Set them ONCE — they are remembered and re-applied
// on every language change, so you never call this again just because the
// player switched language:
greetingLabel.SetArguments(playerName);
scoreLabel.SetArguments(coinsHeld, coinsTotal);

// Reuse one label for different lines:
statusLabel.SetKey("status.saved");
statusLabel.SetKey("status.failed");
